{"source":"def investigate(context, acquire):
    def is_cont(b):
        return 128 <= b <= 191

    def decode_chunk(state, data, final):
        out = []
        i = 0
        n = len(data)
        while i < n:
            b = data[i]
            if state['pending']:
                if is_cont(b):
                    state['pending'].append(b)
                    i += 1
                    if len(state['pending']) == state['need']:
                        seq = state['pending']
                        cp = 0
                        for x in seq:
                            cp = cp * 256 + x
                        if state['need'] == 2:
                            if cp < 128:
                                state['pending'] = None
                                state['need'] = 0
                                raise ValueError
                        elif state['need'] == 3:
                            if cp < 2048 or 55296 <= cp <= 57343:
                                state['pending'] = None
                                state['need'] = 0
                                raise ValueError
                        else:
                            if cp < 65536 or cp > 1114111:
                                state['pending'] = None
                                state['need'] = 0
                                raise ValueError
                        out.append(chr(cp))
                        state['pending'] = None
                        state['need'] = 0
                    continue
                state['pending'] = None
                state['need'] = 0
                raise ValueError
            if b < 128:
                out.append(chr(b))
                i += 1
            elif 192 <= b <= 223:
                state['pending'] = [b]
                state['need'] = 2
                i += 1
            elif 224 <= b <= 239:
                state['pending'] = [b]
                state['need'] = 3
                i += 1
            elif 240 <= b <= 247:
                state['pending'] = [b]
                state['need'] = 4
                i += 1
            else:
                raise ValueError
        if final:
            if state['pending']:
                state['pending'] = None
                state['need'] = 0
                raise ValueError
        return ''.join(out)

    events = context['events']
    state = {'pending': None, 'need': 0}
    count = 0
    status = 'open'
    for ev in events:
        op = ev['op']
        if op == 'feed':
            result = decode_chunk(state, ev['bytes'], False)
            count += len(result)
        elif op == 'finish':
            result = decode_chunk(state, [], True)
            count += len(result)
            status = 'finished'
        elif op == 'reset':
            state = {'pending': None, 'need': 0}
            count = 0
            status = 'open'
    return {'count': count, 'status': status}
